let pageTextObserver;
function applyPageText(){
 pageTextObserver?.disconnect?.();
 const originals=new WeakMap(),attributeOriginals=new WeakMap();
 function apply(root){
 const elements=[...(root.nodeType===1?[root]:[]),...root.querySelectorAll('[placeholder],[aria-label],[alt],[title]')];
 for(const el of elements){if(el.closest('.chat-message,svg'))continue;let saved=attributeOriginals.get(el);if(!saved){saved={};attributeOriginals.set(el,saved);}for(const name of ['placeholder','aria-label','alt','title']){if(!el.hasAttribute(name))continue;const original=saved[name]??el.getAttribute(name);saved[name]=original;if(Object.hasOwn(data.copy||{},original)&&el.getAttribute(name)!==data.copy[original])el.setAttribute(name,data.copy[original]);}}
 const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode()){if(['SCRIPT','STYLE','TEXTAREA','INPUT'].includes(node.parentElement?.tagName)||node.parentElement?.closest('.chat-message,svg,[aria-hidden="true"]'))continue;const original=originals.get(node)||node.nodeValue;originals.set(node,original);const key=original.trim();if(Object.hasOwn(data.copy||{},key)){const value=original.replace(key,()=>data.copy[key]);if(node.nodeValue!==value)node.nodeValue=value;}}}
 if(Object.hasOwn(data.copy||{},document.title))document.title=data.copy[document.title];
 apply(document.body);
 pageTextObserver=new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes){if(node.nodeType===1)apply(node);else if(node.nodeType===3&&node.parentElement)apply(node.parentElement);}});pageTextObserver.observe(document.body,{childList:true,subtree:true});
}

